// Animación "base" · celdas de 16x16 · la base empieza en (2, 4) dentro de cada celda.
config({ name: "base", base: "base.png", cell: [16, 16], origin: [2, 4], colors: [] });

// Receta del dibujo base: los mismos comandos de pxcli que lo dibujaron, en orden.
// Repártela en piezas con nombre para poder moverlas. El orden de dibujo hace de capas:
// lo que se dibuja después queda encima.
part("base", () => {
  fill_rect(2, 0, 8, 1, "#7a4a2a");
  fill_rect(2, 11, 8, 1, "#7a4a2a");
  fill_rect(3, 1, 6, 10, "#cfe8ff");
  fill_rect(0, 0, 1, 1, "transparent");
  fill_rect(4, 2, 4, 3, "#e8c070");
  line(6, 5, 6, 9, "#e8c070");
});

// La pose de reposo tiene que ser idéntica al dibujo base (lo comprueba `pxcli anim check`).
rest(() => {
  draw("base");
});

// Una función por acción: dibuja el frame f desde cero. t va de 0 a 1.
action("caer", { frames: 4, fps: 8, loop: true }, (f, { t }) => {
  draw("base");
});

action("salto", { frames: 3, fps: 8, loop: false }, (f, { t }) => {
  draw("base");
});

// Animación "Reloj Grande" · celdas de 16x16 · la base empieza en (2, 2) dentro de cada celda.
config({ name: "Reloj Grande", base: "base.png", cell: [16, 16], origin: [2, 2], colors: [] });

// Receta del dibujo base, reconstruida a partir de sus píxeles (rectángulos por color).
// Repártela en piezas con nombre para poder moverlas. El orden de dibujo hace de capas:
// lo que se dibuja después queda encima.
part("base", () => {
  fill_rect(2, 0, 8, 1, "#7a4a2a");
  fill_rect(3, 1, 6, 1, "#cfe8ff");
  fill_rect(3, 2, 1, 9, "#cfe8ff");
  fill_rect(4, 2, 4, 3, "#e8c070");
  fill_rect(8, 2, 1, 9, "#cfe8ff");
  fill_rect(4, 5, 2, 6, "#cfe8ff");
  fill_rect(6, 5, 1, 5, "#e8c070");
  fill_rect(7, 5, 1, 6, "#cfe8ff");
  set_pixel(6, 10, "#cfe8ff");
  fill_rect(2, 11, 8, 1, "#7a4a2a");
});

// La pose de reposo tiene que ser idéntica al dibujo base (lo comprueba `pxcli anim check`).
rest(() => {
  draw("base");
});

// Una función por acción: dibuja el frame f desde cero. t va de 0 a 1.
action("anim", { frames: 8, fps: 8, loop: true }, (f, { t }) => {
  draw("base");
});

